/// (`cmd: flutter build apk --flavor store --release` on the android row)
/// is interpolated at job level.
final androidBuildSignatures = [
  RegExp(r'flutter build (apk|appbundle)\b'),
  RegExp(r'fastlane android build_release\b'),
  RegExp(r'matrix\.cmd'),
